with base as (select *, date_format(launch_date, 'MMM yyyy') as launch_date_label from products where size(tags) >= 1 and year(launch_date) = 2023 and category = 'Grocery'), brand_summary as (select brand, category, max(price) as max_price, concat_ws(', ', sort_array(collect_set(brand))) as brand_values from base group by brand, category) select * from brand_summary where max_price >= 1110 order by category, brand limit 1;
